insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:chef','2026-08-11',0,0,0,0,12,0,0,0,4,16,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Japan classifies skilled restaurant cooking primarily by cuisine under 055-01 to 055-04 rather than by a universal Chef seniority code. 055-02 explicitly includes シェフ.','entry_level_basis','Culinary school or workplace apprenticeship can lead into skilled cooking; senior chef responsibility usually follows substantial practical experience. Two reviewed advanced cuisine programmes are direct and one general culinary programme is related.','qualification_note','No universal statutory Chef licence is required to perform the broad occupation. 調理師 is a protected licensed title, but job tag states entry to professional cooking itself does not universally require that licence.','market_scope','Cuisine classifications are not merged into a fabricated exact Chef labour series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:cook','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The broad Cook role is represented across 055-05 chain cooking, 055-06 school meals, 055-07 other institutional catering and 055-99 other cooking rather than one exact code.','entry_level_basis','Commercial cooking can be entered through workplace training or culinary study; three reviewed Japanese culinary programmes are direct study pathways.','qualification_note','No universal statutory Cook licence is required. The 調理師 title is licensed and protected, while specific establishments and food-safety responsibilities can carry separate requirements.','market_scope','Chain, institutional and other cooking groups are preserved separately and are not combined into one exact Cook market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:hotel-manager','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Hotel managers split between 002-01 company managers when management is primary and 056-02 旅館・ホテル支配人 when frontline hospitality/service management is primary.','entry_level_basis','Hospitality or tourism study can support entry, but job tag describes progression through hotel departments and management experience as the common route. One reviewed programme is direct and one is related.','qualification_note','No universal statutory Hotel Manager licence applies; venue, food, liquor or other regulated operations can impose separate role-specific requirements.','market_scope','Corporate management and frontline hotel-management classifications are not merged into one unsupported exact series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:restaurant-manager','2026-08-11',0,0,0,0,12,0,0,0,5,17,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Restaurant managers can fall under 002-01 when corporate management is primary, 003-99 for qualifying owner-managed businesses, or 056-01 when frontline service/restaurant operations are primary.','entry_level_basis','Hospitality study is relevant, but management usually develops from restaurant operations, customer service, staffing, purchasing and commercial responsibility; two reviewed programmes are related pathways.','qualification_note','No universal statutory Restaurant Manager licence applies. Food-hygiene, liquor and venue responsibilities can require separate designated persons or credentials.','market_scope','Management and service-centred restaurant-manager groups are preserved separately rather than combined into one exact market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:baker','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 072-01 directly includes bread production workers and bakers; automated production-equipment operators are classified separately under 068-01.','entry_level_basis','Bakery work can be entered without a mandatory academic credential; one reviewed advanced bread programme is direct and one confectionery programme is related.','qualification_note','No universal statutory Baker licence applies. パン製造技能士 can support progression but is not universal entry permission; independent food businesses have separate hygiene and business obligations.','market_scope','CampCareer does not mix 068-01 automated production operators into the primary baker classification.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:tourism-manager','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','There is no standalone MHLW Tourism Manager code. Tourism management can combine organisational management under 002-01 with tour and travel-product planning explicitly listed in 033-03.','entry_level_basis','Tourism and hospitality study plus operating, commercial and supplier-management experience provide common foundations; two reviewed Japanese tourism programmes are direct academic pathways.','qualification_note','No universal Tourism Manager licence applies. Narrow travel operations such as itinerary management or travel-business responsibilities can carry separate statutory or training requirements.','market_scope','Management, travel planning, sales and guiding occupations are not merged into a fabricated Tourism Manager labour series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:event-planner','2026-08-11',0,0,0,0,12,0,0,0,5,17,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 033-03 directly lists イベントプランナー within planning and research clerical occupations. Creative production leadership can fall separately under 020-99 and is not automatically rolled into this profile.','entry_level_basis','Event, hospitality, tourism, marketing and communications study can support entry; the two reviewed Japanese programmes are related rather than occupational qualifications.','qualification_note','No universal statutory Event Planner licence applies. Venue, safety, alcohol, entertainment and public-space permissions depend on the event and organiser.','market_scope','033-03 is broader than event planning alone, so group-level market data are not treated as exact Event Planner observations.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:hospitality-supervisor','2026-08-11',0,0,0,0,12,0,0,0,5,17,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Japan has no single generic Hospitality Supervisor code. Frontline supervision is distributed across restaurant management 056-01, hotel management 056-02, food service 056-03, hotel front/service 056-04/05 and housekeeping work such as 096-03.','entry_level_basis','Hospitality study plus frontline experience commonly leads to shift-lead and supervisory responsibility; one reviewed hospitality-tourism programme is direct and one tourism programme is related.','qualification_note','No universal statutory Hospitality Supervisor licence applies. Food, liquor, gaming, accommodation and safety responsibilities can carry venue-specific credentials or designated-person requirements.','market_scope','Distinct restaurant, hotel, service and housekeeping classifications are not aggregated into one exact supervisor market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11')
